-- Register every user-facing TMS/VMS/FMS/HR business action as a button under its page menu.
-- Existing rows are retained so current role grants stay attached to the same menu ids.

update public.sys_menu child
set name = case child.name
  when 'TmsDriverAdd' then 'TmsDriver:Add'
  when 'TmsDriverEdit' then 'TmsDriver:Edit'
  when 'TmsDriverDelete' then 'TmsDriver:Delete'
  else child.name
end,
update_by = 'codex-business-permission-migration',
update_time = now()
from public.sys_menu parent
where child.parent_id = parent.id
  and parent.name = 'TmsDriver'
  and child.type = 'button'
  and child.name in ('TmsDriverAdd', 'TmsDriverEdit', 'TmsDriverDelete');

