  loop
    select id
      into parent_menu_id
      from public.sys_menu
     where name = permission_item->>'menu'
       and type is distinct from 'button'
     order by create_time
     limit 1;

    if parent_menu_id is null then
      raise exception 'Business permission parent menu not found: %', permission_item->>'menu';
    end if;

    if not exists (
      select 1
        from public.sys_menu
       where parent_id = parent_menu_id
         and type = 'button'
         and name = permission_item->>'code'
    ) then
      insert into public.sys_menu (
        id,
        parent_id,
        name,
        path,
        component,
        meta,
        sort,
        type,
        create_by,
        create_time,
        update_by,
        update_time
      )
      values (
        gen_random_uuid(),
        parent_menu_id,
        permission_item->>'code',
        '',
        '',
        jsonb_build_object(
          'icon', '',
          'link', '',
          'roles', '[]'::jsonb,
          'title', permission_item->>'title',
          'is_hide', false,
          'fixed_tab', false,
          'is_enable', true,
          'is_iframe', false,
          'keep_alive', false,
          'show_badge', false,
          'active_path', '',
          'is_hide_tab', false,
          'is_full_page', false,
          'is_auth_button', true,
          'show_text_badge', ''
        ),
        (permission_item->>'sort')::integer,
        'button',
        'codex-business-permission-migration',
        now(),
        null,
        now()
      );
    end if;

    parent_menu_id := null;
  end loop;
end
$migration$;

-- Follow-up actions discovered during the final page audit. Kept as an idempotent
-- set so existing role grants and menu ids are never replaced.
with permission_item(menu_name, title, code, sort) as (
  values
    ('TmsOrderOpen', '运单标签双打', 'TmsOrderOpen:DoublePrint', 5),
    ('TmsPendingWaybillList', '导出', 'TmsPendingWaybillList:Export', 4),
    ('TmsLoadedWaybillList', '导出', 'TmsLoadedWaybillList:Export', 2),
    ('TmsLoadedWaybillList', '打印', 'TmsLoadedWaybillList:Print', 3),
    ('TmsInTransitMonitor', '联系司机', 'TmsInTransitMonitor:ContactDriver', 3),
    ('TmsInTransitMonitor', '发送在途提醒', 'TmsInTransitMonitor:SendReminder', 4),
    ('VehicleInspectionExpiry', '查看工单', 'VehicleInspectionExpiry:View', 1),
    ('VehicleInsuranceExpiry', '查看工单', 'VehicleInsuranceExpiry:View', 1),
    ('VehicleMaintenanceExpiry', '查看工单', 'VehicleMaintenanceExpiry:View', 1),
    ('VehiclePartServiceLife', '查看工单', 'VehiclePartServiceLife:View', 1),
    ('VehicleServiceLife', '查看工单', 'VehicleServiceLife:View', 1)
),
parent_menu as (
  select permission_item.*, parent.id as parent_id
  from permission_item
  join public.sys_menu parent
    on parent.name = permission_item.menu_name
   and parent.type is distinct from 'button'
)
insert into public.sys_menu (
  id, parent_id, name, path, component, meta, sort, type,
  create_by, create_time, update_by, update_time
)
select
  gen_random_uuid(),
  parent_menu.parent_id,
  parent_menu.code,
  '',
  '',
  jsonb_build_object(
    'icon', '',
    'link', '',
    'roles', '[]'::jsonb,
    'title', parent_menu.title,
    'is_hide', false,
    'fixed_tab', false,
    'is_enable', true,
    'is_iframe', false,
    'keep_alive', false,
    'show_badge', false,
    'active_path', '',
    'is_hide_tab', false,
    'is_full_page', false,
    'is_auth_button', true,
    'show_text_badge', ''
  ),
  parent_menu.sort,
  'button',
  'codex-business-permission-migration',
  now(),
  null,
  now()
from parent_menu
where not exists (
  select 1
  from public.sys_menu existing
  where existing.parent_id = parent_menu.parent_id
    and existing.type = 'button'
    and existing.name = parent_menu.code
);

